from __future__ import annotations

import hashlib
import json
import os
from collections import Counter
from dataclasses import dataclass
from fractions import Fraction
from pathlib import Path
from typing import Any

from .splits import (
    SET_NAMES,
    SplitError,
    assign,
    category_key,
    category_name,
    validate_name,
    validate_ratios,
)


STATE_DIRECTORY = ".vision-workbench"
MANIFEST_NAME = "manifest.json"
SPLITS_DIRECTORY = "splits"
SPLIT_SCHEMA_VERSION = 1


@dataclass(frozen=True)
class ImportResult:
    digest: str
    added: bool


@dataclass(frozen=True)
class SplitPlanResult:
    name: str
    created: bool
    plan: dict[str, Any]


class DatasetStore:
    def __init__(self, root: Path) -> None:
        self.root = root.resolve()
        self.state_directory = self.root / STATE_DIRECTORY
        self.manifest_path = self.state_directory / MANIFEST_NAME
        self.splits_directory = self.state_directory / SPLITS_DIRECTORY

    def initialize(self) -> None:
        self.state_directory.mkdir(parents=True, exist_ok=True)
        if not self.manifest_path.exists():
            self._write({"schema_version": 1, "items": []})

    def add(self, source: Path, label: str | None = None) -> ImportResult:
        self.initialize()
        file_path = source.resolve(strict=True)
        if not file_path.is_file():
            raise ValueError(f"Not a regular file: {source}")
        digest = self._digest(file_path)
        manifest = self._read()
        if any(item["sha256"] == digest for item in manifest["items"]):
            return ImportResult(digest=digest, added=False)
        manifest["items"].append(
            {
                "sha256": digest,
                "source": str(file_path),
                "size": file_path.stat().st_size,
                "label": label,
            }
        )
        manifest["items"].sort(key=lambda item: item["sha256"])
        self._write(manifest)
        return ImportResult(digest=digest, added=True)

    def summary(self) -> dict[str, Any]:
        self.initialize()
        items = self._read()["items"]
        labels = Counter(item["label"] or "unlabeled" for item in items)
        return {
            "items": len(items),
            "bytes": sum(item["size"] for item in items),
            "labels": dict(sorted(labels.items())),
        }

    # ------------------------------------------------------------------
    # Split plans
    # ------------------------------------------------------------------

    def create_split(
        self, name: str, seed: int, ratios: list[float | int | str | Fraction]
    ) -> SplitPlanResult:
        """Create (or reuse) a named train/validation/test plan.

        The plan snapshots every sample currently in the manifest.  A
        second call with the same name returns the stored plan unchanged
        when the inputs match; otherwise it reports a name conflict.
        """
        validate_name(name)
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise SplitError(f"Seed must be an integer, got {seed!r}")
        fraction_ratios = validate_ratios(ratios)

        self.initialize()
        items = self._read()["items"]

        # assign() validates identities and performs the stratification.
        assignment = assign(items, fraction_ratios, seed)

        snapshot = [
            {
                "sha256": item["sha256"],
                "label": item.get("label"),
                "source": item.get("source"),
            }
            for item in sorted(items, key=lambda item: item["sha256"])
        ]
        plan_payload = self._build_plan(name, seed, fraction_ratios, snapshot, assignment)

        plan_path = self._split_path(name)
        if plan_path.exists():
            existing = self._read_split(plan_path)
            if self._same_inputs(existing, seed, fraction_ratios, snapshot):
                return SplitPlanResult(name=name, created=False, plan=existing)
            raise SplitError(
                f"Split plan {name!r} already exists with different seed, "
                "ratios or samples; choose another name"
            )

        self._write_json_atomic(plan_path, plan_payload)
        return SplitPlanResult(name=name, created=True, plan=plan_payload)

    def get_split(self, name: str) -> dict[str, Any]:
        """Return the stored plan payload, or raise if it does not exist."""
        validate_name(name)
        plan_path = self._split_path(name)
        if not plan_path.exists():
            raise SplitError(f"Split plan not found: {name}")
        return self._read_split(plan_path)

    def _split_path(self, name: str) -> Path:
        # validate_name() has already ruled out path separators and "..".
        return self.splits_directory / f"{name}.json"

    def _build_plan(
        self,
        name: str,
        seed: int,
        ratios: tuple[Fraction, Fraction, Fraction],
        snapshot: list[dict[str, Any]],
        assignment: dict[str, str],
    ) -> dict[str, Any]:
        sets = {set_name: [] for set_name in SET_NAMES}
        for sample in snapshot:
            set_name = assignment[sample["sha256"]]
            sets[set_name].append(
                {
                    "sha256": sample["sha256"],
                    "label": category_name(category_key(sample["label"])),
                    "source": sample["source"],
                }
            )

        set_summaries: dict[str, Any] = {}
        for set_name in SET_NAMES:
            members = sets[set_name]
            distribution = Counter(member["label"] for member in members)
            set_summaries[set_name] = {
                "samples": len(members),
                "distribution": dict(sorted(distribution.items())),
                "members": [
                    {
                        "sha256": member["sha256"],
                        "label": member["label"],
                        "source": member["source"],
                    }
                    for member in members
                ],
            }

        overall = Counter(
            category_name(category_key(sample["label"])) for sample in snapshot
        )
        return {
            "schema_version": SPLIT_SCHEMA_VERSION,
            "name": name,
            "seed": seed,
            "ratios": {
                set_name: str(ratios[i]) for i, set_name in enumerate(SET_NAMES)
            },
            "samples": {
                "total": len(snapshot),
                "distribution": dict(sorted(overall.items())),
            },
            "sets": set_summaries,
        }

    @staticmethod
    def _same_inputs(
        existing: dict[str, Any],
        seed: int,
        ratios: tuple[Fraction, Fraction, Fraction],
        snapshot: list[dict[str, Any]],
    ) -> bool:
        """Whether a stored plan was created from the exact same inputs."""
        if existing.get("seed") != seed:
            return False
        stored_ratios = existing.get("ratios")
        if not isinstance(stored_ratios, dict):
            return False
        for i, set_name in enumerate(SET_NAMES):
            stored = stored_ratios.get(set_name)
            if not isinstance(stored, str) or Fraction(stored) != ratios[i]:
                return False

        # Reuse requires the exact same sample identities with the exact
        # same creation-time labels; recorded sources are informational and
        # do not participate in the identity (the snapshot itself is the
        # decision input, per the feature contract).
        current = sorted(
            (sample["sha256"], category_name(category_key(sample.get("label"))))
            for sample in snapshot
        )
        stored: list[tuple[str, str]] = []
        sets = existing["sets"]
        for set_name in SET_NAMES:
            for member in sets[set_name]["members"]:
                stored.append((member["sha256"], member.get("label")))
        return sorted(stored) == current

    def _read_split(self, plan_path: Path) -> dict[str, Any]:
        try:
            data = json.loads(plan_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as error:
            raise SplitError(f"Cannot read split plan: {error}") from error
        self._validate_split_payload(data)
        return data

    @staticmethod
    def _validate_split_payload(data: Any) -> None:
        if not isinstance(data, dict):
            raise SplitError("Split plan record is malformed")
        if data.get("schema_version") != SPLIT_SCHEMA_VERSION:
            raise SplitError("Unsupported split plan schema version")
        if not isinstance(data.get("name"), str):
            raise SplitError("Split plan record is missing its name")
        if not isinstance(data.get("seed"), int) or isinstance(data.get("seed"), bool):
            raise SplitError("Split plan record is missing its seed")
        ratios = data.get("ratios")
        if not isinstance(ratios, dict):
            raise SplitError("Split plan record is missing its ratios")
        ratio_values = []
        for set_name in SET_NAMES:
            value = ratios.get(set_name)
            if not isinstance(value, str):
                raise SplitError(f"Split plan record is missing ratio for {set_name}")
            ratio_values.append(value)
        try:
            validate_ratios(ratio_values)
        except SplitError as error:
            raise SplitError(f"Split plan record has invalid ratios: {error}") from error

        samples = data.get("samples")
        if (
            not isinstance(samples, dict)
            or not isinstance(samples.get("total"), int)
            or isinstance(samples.get("total"), bool)
        ):
            raise SplitError("Split plan record is missing its sample summary")
        if not isinstance(samples.get("distribution"), dict):
            raise SplitError("Split plan record is missing its class distribution")
        sets = data.get("sets")
        if not isinstance(sets, dict):
            raise SplitError("Split plan record is missing its set assignments")

        seen: set[str] = set()
        overall: Counter[str] = Counter()
        for set_name in SET_NAMES:
            set_payload = sets.get(set_name)
            if not isinstance(set_payload, dict):
                raise SplitError(f"Split plan record is missing set {set_name}")
            members = set_payload.get("members")
            if not isinstance(members, list):
                raise SplitError(f"Split plan record is missing members for {set_name}")
            if set_payload.get("samples") != len(members):
                raise SplitError(f"Split plan record has a bad count for {set_name}")
            distribution = Counter()
            for member in members:
                if (
                    not isinstance(member, dict)
                    or not isinstance(member.get("sha256"), str)
                    or not isinstance(member.get("label"), str)
                    or not isinstance(member.get("source"), str)
                ):
                    raise SplitError(f"Split plan record has a bad member in {set_name}")
                digest = member["sha256"]
                if digest in seen:
                    raise SplitError(
                        f"Split plan record lists {digest} in more than one set"
                    )
                seen.add(digest)
                distribution[member["label"]] += 1
                overall[member["label"]] += 1
            if dict(sorted(distribution.items())) != {
                key: value for key, value in sorted(set_payload.get("distribution", {}).items())
            }:
                raise SplitError(
                    f"Split plan record has a mismatched distribution for {set_name}"
                )
        if samples["total"] != len(seen):
            raise SplitError("Split plan record has a mismatched sample total")
        if dict(sorted(overall.items())) != {
            key: value for key, value in sorted(samples["distribution"].items())
        }:
            raise SplitError("Split plan record has a mismatched class distribution")

    def _write_json_atomic(self, path: Path, payload: dict[str, Any]) -> None:
        """Write via a temp file + fsync + atomic replace.

        A reader therefore observes either no plan or the complete plan,
        never a partial one.
        """
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(f".{path.name}.tmp")
        try:
            with temporary.open("w", encoding="utf-8") as stream:
                stream.write(json.dumps(payload, ensure_ascii=False, indent=2) + "\n")
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, path)
            self._fsync_directory(path.parent)
        except OSError:
            temporary.unlink(missing_ok=True)
            raise

    @staticmethod
    def _fsync_directory(directory: Path) -> None:
        try:
            descriptor = os.open(directory, os.O_RDONLY)
        except OSError:
            return
        try:
            os.fsync(descriptor)
        except OSError:
            pass
        finally:
            os.close(descriptor)

    def _read(self) -> dict[str, Any]:
        try:
            data = json.loads(self.manifest_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as error:
            raise ValueError(f"Cannot read dataset manifest: {error}") from error
        if data.get("schema_version") != 1 or not isinstance(data.get("items"), list):
            raise ValueError("Unsupported dataset manifest")
        return data

    def _write(self, data: dict[str, Any]) -> None:
        temporary = self.manifest_path.with_suffix(".tmp")
        temporary.write_text(
            json.dumps(data, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        temporary.replace(self.manifest_path)

    @staticmethod
    def _digest(path: Path) -> str:
        hasher = hashlib.sha256()
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                hasher.update(chunk)
        return hasher.hexdigest()

"""Stratified train/validation/test split planning.

A plan allocates every sample to exactly one of three sets.  Exact rational
arithmetic (:mod:`fractions`) drives the allocation so that, for every
class *and* for the dataset as a whole, each set's sample count differs
from its proportional expectation by strictly less than one.

Assignments derive solely from sample identities (content digests), labels
and the integer seed, so they are independent of import order, manifest
ordering, workspace location and process restarts.
"""

from __future__ import annotations

import hashlib
import math
from fractions import Fraction
from typing import Any, Sequence

# Sentinel for samples without a label.  An object (not the string
# "unlabeled") keeps a real class literally named "unlabeled" separate.
UNLABELED = object()

SET_NAMES = ("train", "validation", "test")


class SplitError(ValueError):
    """A split parameter or record is invalid."""


def category_key(label: Any) -> Any:
    """Stratum key for a manifest label value.

    ``None`` and the empty string both mean "unlabeled", matching
    :meth:`DatasetStore.summary`; any other label is taken literally.
    """
    if label is None or label == "":
        return UNLABELED
    return label


def category_name(key: Any) -> str:
    """Render a stratum key for JSON output.

    The unlabeled stratum renders as the empty string (which mirrors the
    manifest's empty-label meaning); a genuine class literally named
    ``"unlabeled"`` therefore stays distinguishable.
    """
    return "" if key is UNLABELED else str(key)


def _sort_key(key: Any) -> tuple[int, str]:
    return (0 if key is UNLABELED else 1, category_name(key))


def validate_name(name: str) -> str:
    if not isinstance(name, str) or not name.strip():
        raise SplitError("Split plan name must not be empty or only whitespace")
    if "/" in name or "\\" in name:
        raise SplitError("Split plan name must not contain '/' or '\\'")
    if name in (".", ".."):
        raise SplitError("Split plan name must not be '.' or '..'")
    return name


def parse_ratio(value: Any) -> Fraction:
    """Parse one ratio as a finite number in the closed interval [0, 1]."""
    if isinstance(value, bool):
        raise SplitError(f"Ratio must be a number, got {value!r}")
    if isinstance(value, float):
        if not math.isfinite(value):
            raise SplitError(f"Ratio must be finite, got {value!r}")
        # Use the shortest decimal that round-trips, so 0.1 means 1/10
        # rather than its binary approximation.
        value = repr(value)
    try:
        if isinstance(value, Fraction):
            ratio = value
        elif isinstance(value, int):
            ratio = Fraction(value)
        elif isinstance(value, str):
            ratio = Fraction(value)
        else:
            raise SplitError(f"Ratio must be a number, got {value!r}")
    except (ValueError, ZeroDivisionError, ArithmeticError, OverflowError):
        raise SplitError(f"Ratio must be a finite number, got {value!r}") from None
    if ratio < 0 or ratio > 1:
        raise SplitError(
            f"Ratio must be between 0 and 1 (inclusive), got {value!r}"
        )
    return ratio


def validate_ratios(ratios: Sequence[Any]) -> tuple[Fraction, Fraction, Fraction]:
    if len(ratios) != 3:
        raise SplitError("Exactly three ratios (train, validation, test) are required")
    parsed = tuple(parse_ratio(value) for value in ratios)
    if sum(parsed, Fraction(0)) != 1:
        raise SplitError("Ratios must sum to exactly 1")
    return parsed  # type: ignore[return-value]


def allocation_table(
    strata_counts: dict[Any, int], ratios: tuple[Fraction, Fraction, Fraction]
) -> dict[Any, tuple[int, int, int]]:
    """Allocate integer ``(train, validation, test)`` counts per stratum.

    Construction: every cell starts at ``floor(N_c * p_s)``; each stratum
    then distributes its leftover free units (at most two per row) and each
    column total must land on ``floor`` or ``ceil`` of its own expectation.
    A free unit may only enter a non-integral cell.  An integral placement
    always exists (controlled rounding of the fractional-parts table); the
    small max-flow below searches the deterministic floor/ceil choices.
    Every used cell ends at ``floor`` or ``ceil`` of its expectation and
    every column total at ``floor``/``ceil`` of its, hence every
    discrepancy is strictly below one.
    """
    strata = sorted(strata_counts, key=_sort_key)
    total = sum(strata_counts.values())

    floors: dict[Any, list[int]] = {}
    parts: dict[Any, list[Fraction]] = {}
    for c in strata:
        expectation = [Fraction(strata_counts[c]) * ratios[j] for j in range(3)]
        floors[c] = [e.numerator // e.denominator for e in expectation]
        parts[c] = [e - floors[c][j] for j, e in enumerate(expectation)]

    # Fractional column sums S_j; a column receives floor(S_j) or
    # ceil(S_j) free units.  sum_j S_j is the integer number of free
    # units, so the fractional parts sum to an integer k: exactly k
    # non-integral columns round up.  A column whose S_j is integral
    # cannot round up (that would be a discrepancy of exactly one), so
    # the size-k subsets are tried until a flow matches every row.
    column_sums = [sum((parts[c][j] for c in strata), Fraction(0)) for j in range(3)]
    column_base = [s.numerator // s.denominator for s in column_sums]
    row_supply = {c: int(sum(parts[c])) for c in strata}
    extra_needed = sum(row_supply.values()) - sum(column_base)
    eligible = [j for j in range(3) if column_sums[j] != column_base[j]]

    flows = _controlled_rounding(
        strata, parts, row_supply, column_base, extra_needed, eligible
    )

    table: dict[Any, tuple[int, int, int]] = {}
    for c in strata:
        table[c] = tuple(floors[c][j] + flows[c][j] for j in range(3))  # type: ignore[assignment]
        if sum(table[c]) != strata_counts[c]:
            raise SplitError("Internal error: stratum count mismatch")  # pragma: no cover
    for j in range(3):
        column_total = sum(table[c][j] for c in strata)
        expect_total = Fraction(total) * ratios[j]
        if abs(Fraction(column_total) - expect_total) >= 1:
            raise SplitError("Internal error: total count mismatch")  # pragma: no cover
    return table


def _controlled_rounding(
    strata: Sequence[Any],
    parts: dict[Any, list[Fraction]],
    row_supply: dict[Any, int],
    column_base: list[int],
    extra_needed: int,
    eligible: Sequence[int],
) -> dict[Any, list[int]]:
    """Place every row's free units on non-integral cells.

    Column j receives ``column_base[j]`` units, plus one for each member
    of a size-``extra_needed`` subset of eligible columns (its total then
    rounds ``S_j`` to floor or ceil).  Candidate subsets are tried in a
    fixed order; the fractional parts themselves prove the rounded
    polytope has an integral vertex, so one candidate always yields a
    full-value flow.
    """
    from itertools import combinations

    if extra_needed == 0:
        candidates: list[tuple[int, ...]] = [()]
    else:
        candidates = list(combinations(eligible, extra_needed))

    last_error: Exception | None = None
    for extra in candidates:
        demand = column_base[:]
        for j in extra:
            demand[j] += 1
        try:
            return _integral_flow(strata, parts, row_supply, demand)
        except SplitError as error:  # candidate infeasible, try next
            last_error = error
    raise SplitError(
        f"Internal error: cannot satisfy split proportions: {last_error}"
    )  # pragma: no cover


def _integral_flow(
    strata: Sequence[Any],
    parts: dict[Any, list[Fraction]],
    row_supply: dict[Any, int],
    column_demand: list[int],
) -> dict[Any, list[int]]:
    """Max-flow placement; raises unless every free unit is placed."""
    source = ("s",)
    sink = ("t",)
    row_nodes = [("r", i) for i in range(len(strata))]
    col_nodes = [("c", j) for j in range(3)]
    residual: dict[Any, dict[Any, int]] = {source: {}, sink: {}}
    for node in row_nodes + col_nodes:
        residual[node] = {}

    def add_edge(u: Any, v: Any, capacity: int) -> None:
        residual[u][v] = capacity
        residual[v].setdefault(u, 0)

    required = 0
    for i, c in enumerate(strata):
        supply = row_supply[c]
        required += supply
        if supply:
            add_edge(source, row_nodes[i], supply)
        for j in sorted(range(3), key=lambda k: (-parts[c][k], k)):
            if parts[c][j] > 0:
                add_edge(row_nodes[i], col_nodes[j], 1)
    for j, node in enumerate(col_nodes):
        add_edge(node, sink, column_demand[j])

    pushed = 0
    while pushed < required:
        path = _augmenting_path(residual, source, sink, row_nodes, col_nodes)
        if path is None:
            raise SplitError("no feasible integral placement")
        for u, v in zip(path, path[1:]):
            residual[u][v] -= 1
            residual[v][u] += 1
        pushed += 1

    flows = {c: [0, 0, 0] for c in strata}
    for i, c in enumerate(strata):
        for j, col in enumerate(col_nodes):
            # Forward edge capacity was 1; residual reverse flow of 1
            # means the unit was placed in this cell.
            flows[c][j] = residual[col].get(row_nodes[i], 0)
    return flows


def _augmenting_path(
    residual: dict[Any, dict[Any, int]],
    source: Any,
    sink: Any,
    row_nodes: Sequence[Any],
    col_nodes: Sequence[Any],
) -> list[Any] | None:
    """Breadth-first augmenting path with fixed node traversal order."""
    order = [source, *row_nodes, *col_nodes, sink]
    previous: dict[Any, Any] = {source: None}
    queue = [source]
    head = 0
    while head < len(queue):
        node = queue[head]
        head += 1
        for neighbor in order:
            if neighbor in previous:
                continue
            if residual.get(node, {}).get(neighbor, 0) > 0:
                previous[neighbor] = node
                if neighbor == sink:
                    path = [sink]
                    while path[-1] is not source:
                        path.append(previous[path[-1]])
                    path.reverse()
                    return path
                queue.append(neighbor)
    return None


def seeded_order(digests: Sequence[str], seed: int) -> list[str]:
    """Deterministic seed-driven order of the given digests.

    Each digest gets a sort key ``H(seed || digest)`` from SHA-256, with
    the digest itself breaking ties.  Unlike :mod:`random`, this stream is
    defined by the hash algorithm itself, so it is stable across Python
    versions and only depends on the digest set and the seed.
    """
    seed_bytes = str(seed).encode("utf-8")
    return sorted(
        digests,
        key=lambda digest: (
            hashlib.sha256(seed_bytes + digest.encode("utf-8")).digest(),
            digest,
        ),
    )


def assign(samples: Sequence[dict[str, Any]], ratios: Sequence[Any], seed: Any) -> dict[str, str]:
    """Return ``{digest: set_name}`` for the given manifest-like samples.

    Each sample mapping must contain ``sha256`` and ``label`` keys.
    """
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise SplitError(f"Seed must be an integer, got {seed!r}")
    ratio_values = validate_ratios(ratios)

    digests: list[str] = []
    seen: set[str] = set()
    strata_counts: dict[Any, int] = {}
    stratum_of: dict[str, Any] = {}
    for sample in samples:
        if not isinstance(sample, dict):
            raise SplitError("Every sample record must be an object")
        digest = sample.get("sha256")
        if not isinstance(digest, str) or not digest:
            raise SplitError("Every sample needs a non-empty 'sha256' identity")
        if digest in seen:
            raise SplitError(f"Duplicate sample identity in manifest: {digest}")
        seen.add(digest)
        key = category_key(sample.get("label"))
        stratum_of[digest] = key
        strata_counts[key] = strata_counts.get(key, 0) + 1
        digests.append(digest)

    table = allocation_table(strata_counts, ratio_values)
    positions = {digest: i for i, digest in enumerate(seeded_order(digests, seed))}

    assignment: dict[str, str] = {}
    for key, row in table.items():
        members = sorted(
            (d for d in digests if stratum_of[d] == key),
            key=lambda d: positions[d],
        )
        start = 0
        for j, count in enumerate(row):
            for digest in members[start : start + count]:
                assignment[digest] = SET_NAMES[j]
            start += count
    return assignment

